import ast, sys
src = open('main.py').read()
tree = ast.parse(src)
# find assigned-but-unused names at function level (rough check)
assigned = {}
used = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name):
        if isinstance(node.ctx, ast.Store):
            assigned.setdefault(node.id, node.lineno)
        else:
            used.add(node.id)
unused = {k: v for k, v in assigned.items() if k not in used and not k.startswith('_')}
print('possibly unused:', unused)
print('lines:', len(src.splitlines()))
